mapper.select:
SELECT COUNT(*) AS totalPay, SUM(CASE WHEN bill_status = '已欠费' THEN 1 ELSE 0 END) AS arrearsCount, SUM(COALESCE(fee_amount, 0)) AS totalIncome, CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN bill_status = '已缴费' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) ELSE 0 END AS payRate FROM parking_payment WHERE deleted = FALSE
AND pay_time >= #{startTime}
AND pay_time <= #{endTime}

SELECT DATE_FORMAT(pay_time, '%Y-%m-%d') AS date, SUM(COALESCE(fee_amount, 0)) AS income FROM parking_payment WHERE deleted = FALSE
AND pay_time >= #{startTime}
AND pay_time <= #{endTime}
GROUP BY DATE_FORMAT(pay_time, '%Y-%m-%d') ORDER BY date

SELECT DATE_FORMAT(pay_time, '%Y-%m-%d') AS date, COUNT(*) AS count FROM parking_payment WHERE deleted = FALSE
AND pay_time >= #{startTime}
AND pay_time <= #{endTime}
GROUP BY DATE_FORMAT(pay_time, '%Y-%m-%d') ORDER BY date
